import { registerModule } from '../../core/lifecycle';
import { watchElement } from '../../core/observer';
import { wasApplied, markApplied } from '../../utils/dom';
import { createIcon } from '../../utils/icons';
import { schedule } from '../../core/scheduler';

let stopWatching;

function enhanceCards(root = document) {
    const cards = root.querySelectorAll(
        '.card, .overflowPortraitCard, .overflowBackdropCard, .visualCardBox'
    );

    cards.forEach((card) => {
        if (wasApplied(card, 'ptvCard')) return;

        markApplied(card, 'ptvCard');
        card.classList.add('ptv-card');

        const imageContainer =
            card.querySelector('.cardImageContainer')
            || card.querySelector('.cardPadder')
            || card.querySelector('.cardBox')
            || card;

        if (imageContainer.querySelector('.ptv-card-play-pill')) return;

        const pill = document.createElement('div');
        pill.className = 'ptv-card-play-pill';

        const icon = createIcon('play', 'ptv-card-play-icon');
        const label = document.createElement('span');
        label.textContent = 'Play';

        pill.append(icon, label);
        imageContainer.appendChild(pill);
    });
}

function init() {
    enhanceCards();

stopWatching = watchElement(
    '.itemsContainer, .sections',
    () => {
        schedule(
            'ptv-cards-refresh',
            () => enhanceCards(document)
        );
    }
);
}

function destroy() {
    stopWatching?.();
    stopWatching = null;
}

registerModule({
    name: 'cards',
    init,
    destroy,
    refresh: () => enhanceCards()
});
